INSERT INTO public.news_articles (
  id, slug, title, excerpt, content, category, status, featured,
  image_url, author, author_role, read_time, tags, source, source_url,
  published_at, updated_at
) VALUES (
  'article-01', 'npl-season-3-schedule-venues-announced', 'NPL Season 3 Schedule & TU Ground Fixture Plan: 26 October – 21 November 2026', 'All 32 fixtures for Nepal Premier League Season 3 will be held at TU International Cricket Stadium, Kirtipur, running from 26 October to 21 November 2026. The opening match — Lumbini Lions vs Sudurpaschim Royals — is scheduled for 26 October at 5:00 PM NPT.',
  '["Nepal Premier League Season 3 is scheduled to run from 9 Kartik 2083 BS (26 October 2026) to 5 Mangsir 2083 BS (21 November 2026), according to the fixture calendar published on the NPL Hub Nepal schedule page. The tournament dates are consistent with the fixtures listed at nplhubnepal.vercel.app/schedule.","The opening match of the tournament is Lumbini Lions vs Sudurpaschim Royals on 26 October 2026 (सोमबार, ९ कार्तिक २०८३) at 5:00 PM NPT at TU International Cricket Stadium, Kirtipur.","All 32 matches, including the league stage and four playoff fixtures, will be held at the TU International Cricket Stadium in Kirtipur, Kathmandu. The venue will serve as the sole host ground for the entire tournament.","The league stage consists of 28 matches running from 26 October to 15 November 2026, after which the top four teams on the points table advance to the playoffs. The playoff schedule is: Qualifier 1 (17 November), Eliminator (18 November), Qualifier 2 (19 November), and the Final (21 November 2026).","Eight franchise teams — Kathmandu Gorkhas, Biratnagar Kings, Janakpur Bolts, Pokhara Avengers, Chitwan Rhinos, Lumbini Lions, Karnali Yaks, and Sudurpaschim Royals — will participate in the 27-day competition across 32 T20 fixtures.","NPL Hub Nepal will provide independent coverage of all fixtures, standings, and team information throughout the season. All match times are listed in Nepal Standard Time (NPT, UTC+5:45).","Correction: An earlier version of this article listed incorrect tournament dates (28 November – 21 December 2026). The correct dates are 26 October – 21 November 2026, consistent with the verified fixture schedule. This article has been updated."]'::jsonb,
  'Tournament', 'published', TRUE,
  NULL, 'NPL Hub Nepal Editorial',
  'Editorial', '3 min read', '{}', 'NPL Hub Nepal — verified from fixture schedule at /schedule', NULL,
  '2026-09-25T10:00:00+05:45', '2026-10-03T15:32:00+05:45'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content, category = EXCLUDED.category, status = EXCLUDED.status,
  featured = EXCLUDED.featured, image_url = EXCLUDED.image_url, author = EXCLUDED.author,
  read_time = EXCLUDED.read_time, source = EXCLUDED.source,
  published_at = EXCLUDED.published_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.news_articles (
  id, slug, title, excerpt, content, category, status, featured,
  image_url, author, author_role, read_time, tags, source, source_url,
  published_at, updated_at
) VALUES (
  'article-02', 'marquee-players-draft-highlights', 'NPL Season 3 Player Draft & Squad Registration: What We Know', 'With Season 3 approaching, here is an overview of the squad registration process and what is publicly confirmed about team captains and squad status.',
  '["Nepal Premier League Season 3 squad announcements are expected ahead of the tournament''s opening on 26 October 2026. This article summarises publicly available information about team captains and squad composition.","Captain confirmations as of publication: Rohit Paudel captains the Kathmandu Gorkhas, Aasif Sheikh leads the Biratnagar Kings, Dipendra Singh Airee heads the Janakpur Bolts, and Kushal Malla leads the Pokhara Avengers.","For the remaining four teams — Chitwan Rhinos, Lumbini Lions, Karnali Yaks, and Sudurpaschim Royals — official captain confirmations had not been publicly announced at time of writing. NPL Hub Nepal will update team profiles as verified information becomes available.","The player draft process for NPL is managed by CAN. Overseas and domestic players are allocated to franchise teams through a structured draft. Full squad lists will be published once officially confirmed.","NPL Hub Nepal does not publish unverified squad lists, transfer rumours, or unofficial player assignments. All team profile pages will be updated with confirmed squad information only."]'::jsonb,
  'Teams', 'published', FALSE,
  NULL, 'NPL Hub Nepal Editorial',
  'Editorial', '4 min read', '{}', 'NPL Hub Nepal', NULL,
  '2026-09-23T09:00:00+05:45', '2026-09-23T09:00:00+05:45'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content, category = EXCLUDED.category, status = EXCLUDED.status,
  featured = EXCLUDED.featured, image_url = EXCLUDED.image_url, author = EXCLUDED.author,
  read_time = EXCLUDED.read_time, source = EXCLUDED.source,
