INSERT INTO public.news_articles (
  id, slug, title, excerpt, content, category, status, featured,
  image_url, author, author_role, read_time, tags, source, source_url,
  published_at, updated_at
) VALUES (
  'article-03', 'broadcast-and-streaming-guide-npl-season-3', 'NPL Season 3 Broadcast & Streaming: Placeholder Information', 'Official broadcast and streaming details for NPL Season 3 have not been confirmed by CAN at time of writing. This page will be updated when details are released.',
  '["DRAFT NOTICE: Official broadcast and digital streaming arrangements for Nepal Premier League Season 3 have not been publicly confirmed by the Cricket Association of Nepal at time of writing. The information below reflects general context only.","NPL Hub Nepal will update this article as soon as CAN or an official broadcaster releases streaming and TV coverage details for the 2026 season.","Historically, NPL matches have been broadcast on national Nepali television channels and streamed via official digital platforms. Viewers outside Nepal have been able to access coverage through regional broadcast agreements and official streaming applications.","Once confirmed, NPL Hub Nepal will publish a full guide including TV channels, digital streaming platforms, subscription details, and regional availability for Nepal and international audiences.","For the latest information, follow official CAN announcements and check back on this page."]'::jsonb,
  'Announcements', 'draft', FALSE,
  NULL, 'NPL Hub Nepal Editorial',
  'Editorial', '2 min read', '{}', 'NPL Hub Nepal', NULL,
  '2026-09-20T08:00:00+05:45', '2026-09-20T08:00:00+05:45'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, excerpt = EXCLUDED.excerpt,
