INSERT INTO public.news_articles (
  id, slug, title, excerpt, content, category, status, featured,
  image_url, author, author_role, read_time, tags, source, source_url,
  published_at, updated_at
) VALUES (
  'article-04', 'stadium-expansion-ticketing-update', 'TU International Cricket Stadium & NPL Season 3 Ticketing: What Is Confirmed', 'TU International Cricket Stadium in Kirtipur is the confirmed venue for all NPL Season 3 fixtures. Ticketing arrangements are pending official announcement.',
  '["DRAFT NOTICE: Ticketing prices, booking platforms, and seating arrangements for NPL Season 3 have not been officially announced by the Cricket Association of Nepal at time of writing.","TU International Cricket Stadium, Kirtipur, Kathmandu is the confirmed venue for all 32 matches of NPL Season 3. The stadium has hosted previous NPL editions and major international matches.","The stadium is accessible from central Kathmandu by road. Kirtipur is located approximately 5 km southwest of central Kathmandu.","NPL Hub Nepal will publish detailed ticketing information — including prices, booking methods, gate opening times, and ground regulations — as soon as this is officially confirmed by CAN or the NPL organising committee.","Fans are advised to use only official ticket channels and to verify information through the official CAN website before making any purchase."]'::jsonb,
  'Tournament', 'draft', FALSE,
  NULL, 'NPL Hub Nepal Editorial',
  'Editorial', '3 min read', '{}', 'NPL Hub Nepal', NULL,
  '2026-09-18T09:00:00+05:45', '2026-09-18T09:00:00+05:45'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, excerpt = EXCLUDED.excerpt,
